{
  "implementation": "def solve(case):
    segments = case['segments']
    budget = case['budget']
    n = len(segments)
    minima = [seg['minimum'] for seg in segments]
    capacities = [seg['capacity'] for seg in segments]
    importances = [seg['importance'] for seg in segments]
    allocations = minima[:]
    total_allocated = sum(minima)
    remaining = budget - total_allocated
    if remaining < 0:
        raise ValueError('Budget below minimum sum')
    max_possible = sum(capacities) - total_allocated
    if remaining > max_possible:
        raise ValueError('Budget above maximum sum')
    while remaining > 0:
        best_idx = -1
        best_score = -1.0
        for i in range(n):
            if allocations[i] < capacities[i]:
                score = importances[i] / (allocations[i] + 1)
                if score > best_score:
                    best_score = score
                    best_idx = i
        if best_idx == -1:
            break
        allocations[best_idx] += 1
        remaining -= 1
    total = sum(allocations)
    by_name = {segments[i]['name']: allocations[i] for i in range(n)}
    return {"allocations": allocations, "by_name": by_name, "total": total}"
}
